DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_PAULSOARESJR' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_PAULSOARESJR_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_TEXT_1','The First Night[NEWLINE]Exploration and early memories with later recall[NEWLINE]Science or Culture; flexible peaceful development[NEWLINE][NEWLINE]Acquire different Memories early and preserve the exploration units that can safely earn them. The lasting payoff comes from the acquisition Era and later recall, not from repeating the same event.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_TEXT_2','Scout for contact, a safe Barbarian opportunity and distant discoveries while building the first shelter. Improve genuine resource sites and expand when the economy can support it. An early Memory can pay again in several later Eras.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_TEXT_3','Check which Memories remain unearned rather than continuing to chase one already recorded. Keep a Survivor''s return-home route open and protect its experience; ordinary city infrastructure must carry the economy between recall events.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_TEXT_4','Use accumulated Culture, Science and a developed capital to pursue the chosen victory. Later-era recall is support for a real research or cultural programme, not an endlessly repeatable substitute for it.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_TEXT_5','- Several ordinary exploration and development actions have early rewards.[NEWLINE]- Older Memories become more valuable at later Era transitions.[NEWLINE]- Survivors provide an exploration and preservation theme without a required war.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_TEXT_6','- Each Memory can be earned only once.[NEWLINE]- Map access and safe discovery routes affect the opening opportunities.[NEWLINE]- There is no general combat-strength engine to protect a careless scout or weak border.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_TEXT_7','- Control important approaches and contested settlement sites without donating easy camp or unit rewards.[NEWLINE]- Punish isolated Survivors and cut their safe return paths.[NEWLINE]- Pressure the economy between Era transitions rather than allowing uninterrupted peaceful development.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_TEXT_8','- Waiting until later Eras to complete easy early Memories.[NEWLINE]- Repeating a trigger and expecting another permanent Memory.[NEWLINE]- Sending a veteran far away without a legal, defensible way home.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Saba: A discovery-rich map gives early opportunities that Saba''s location-based city yields do not directly contest.[NEWLINE][NEWLINE]Sol Intellect: Early exploration rewards can support development while Sol is still investing in uninterrupted construction; this does not guarantee a late research lead.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Rapid settlement can close routes and claim useful sites before a cautious explorer converts discoveries into expansion.[NEWLINE][NEWLINE]McPvP: Mobile recon and objective patrols can threaten isolated exploration units and their routes home.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_DESCRIPTION','The First Night');
