INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_LEADER_BACKGROUND','Acquire different Memories early and preserve the exploration units that can safely earn them. The lasting payoff comes from the acquisition Era and later recall, not from repeating the same event.');
