INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_STRATEGY','Acquire different Memories early and preserve the exploration units that can safely earn them. The lasting payoff comes from the acquisition Era and later recall, not from repeating the same event.[NEWLINE][NEWLINE]Scout for contact, a safe Barbarian opportunity and distant discoveries while building the first shelter. Improve genuine resource sites and expand when the economy can support it. An early Memory can pay again in several later Eras.[NEWLINE][NEWLINE]Check which Memories remain unearned rather than continuing to chase one already recorded. Keep a Survivor''s return-home route open and protect its experience; ordinary city infrastructure must carry the economy between recall events.[NEWLINE][NEWLINE]Use accumulated Culture, Science and a developed capital to pursue the chosen victory. Later-era recall is support for a real research or cultural programme, not an endlessly repeatable substitute for it.');
