INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_LEADER_TEXT_2','Scout for contact, a safe Barbarian opportunity and distant discoveries while building the first shelter. Improve genuine resource sites and expand when the economy can support it. An early Memory can pay again in several later Eras.[NEWLINE][NEWLINE]Check which Memories remain unearned rather than continuing to chase one already recorded. Keep a Survivor''s return-home route open and protect its experience; ordinary city infrastructure must carry the economy between recall events.[NEWLINE][NEWLINE]Use accumulated Culture, Science and a developed capital to pursue the chosen victory. Later-era recall is support for a real research or cultural programme, not an endlessly repeatable substitute for it.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_PAULSOARESJR_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Saba: A discovery-rich map gives early opportunities that Saba''s location-based city yields do not directly contest.[NEWLINE][NEWLINE]Sol Intellect: Early exploration rewards can support development while Sol is still investing in uninterrupted construction; this does not guarantee a late research lead.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Rapid settlement can close routes and claim useful sites before a cautious explorer converts discoveries into expansion.[NEWLINE][NEWLINE]McPvP: Mobile recon and objective patrols can threaten isolated exploration units and their routes home.');
